#!/usr/bin/env node

const fs = require('fs');
const path = require('path');

function readMigrations(directory) {
    try {
        // Read all files in the migrations directory
        const files = fs.readdirSync(directory);

        // Filter for SQL files and sort them
        const sqlFiles = files
            .filter(file => file.endsWith('.sql'))
            .sort(); // Simple lexicographical sort

        return sqlFiles;
    } catch (error) {
        if (error.code === 'ENOENT') {
            console.error(`Error: Migrations directory '${directory}' not found.`);
        } else {
            console.error(`Error reading migrations directory: ${error.message}`);
        }
        process.exit(1);
    }
}

function logMigrations(migrations) {
    if (migrations.length === 0) {
        console.log('No migration files found.');
        return;
    }

    console.log('Migration files to be applied (in order):');
    console.log('============================================');

    migrations.forEach((file, index) => {
        console.log(`${index + 1}. ${file}`);
    });

    console.log('============================================');
    console.log(`Total: ${migrations.length} migration file(s)`);
}

// Main function
function main() {
    const migrationsDir = './migrations';
    const migrations = readMigrations(migrationsDir);
    logMigrations(migrations);
}

// Run the script
main();

