const fs = require('fs');
const path = require('path');

// Path to migrations directory
const MIGRATIONS_DIR = './migrations/';

function readMigrations() {
    try {
        // Check if migrations directory exists
        if (!fs.existsSync(MIGRATIONS_DIR)) {
            console.log(`Migrations directory '${MIGRATIONS_DIR}' does not exist.`);
            return [];
        }

        // Read all files in migrations directory
        const files = fs.readdirSync(MIGRATIONS_DIR);

        // Filter for SQL files
        const sqlFiles = files.filter(file => file.endsWith('.sql'));

        if (sqlFiles.length === 0) {
            console.log('No SQL migration files found in migrations directory.');
            return [];
        }

        // Sort files in alphabetical order (which should be chronological order if named properly)
        const sortedFiles = sqlFiles.sort();

        console.log('Migration files found (in order they would be applied):');
        console.log('=====================================================');

        // Log each filename
        sortedFiles.forEach((file, index) => {
            console.log(`${index + 1}. ${file}`);
        });

        return sortedFiles;

    } catch (error) {
        console.error('Error reading migrations:', error.message);
        return [];
    }
}

// Main execution
if (require.main === module) {
    console.log('Starting migration scan...\n');
    readMigrations();
    console.log('\nMigration scan completed.');
}

module.exports = { readMigrations };

