#!/usr/bin/env node

const fs = require('fs');
const path = require('path');

// Directory containing migration files
const MIGRATIONS_DIR = './migrations/';

/**
 * Reads all SQL files from the migrations directory and returns them sorted by filename
 */
function getMigrations() {
  try {
    // Check if migrations directory exists
    if (!fs.existsSync(MIGRATIONS_DIR)) {
      console.log(`Migrations directory '${MIGRATIONS_DIR}' does not exist.`);
      return [];
    }

    // Read all files in the directory
    const files = fs.readdirSync(MIGRATIONS_DIR);

    // Filter for SQL files (files ending with .sql)
    const sqlFiles = files.filter(file => file.endsWith('.sql'));

    if (sqlFiles.length === 0) {
      console.log(`No SQL files found in '${MIGRATIONS_DIR}'.`);
      return [];
    }

    // Sort files alphabetically (which should maintain chronological order if named properly)
    return sqlFiles.sort();
  } catch (error) {
    console.error('Error reading migrations directory:', error.message);
    return [];
  }
}

/**
 * Main function that logs all migration files in order
 */
function logMigrations() {
  console.log('Reading migration files from:', MIGRATIONS_DIR);
  console.log('----------------------------------------');

  const migrations = getMigrations();

  if (migrations.length === 0) {
    console.log('No migrations to apply.');
    return;
  }

  console.log(`Found ${migrations.length} migration(s) to apply:`);
  console.log('----------------------------------------');

  migrations.forEach((file, index) => {
    console.log(`${index + 1}. ${file}`);
  });

  console.log('----------------------------------------');
  console.log('Migration files listed above would be applied in this order.');
}

// Parse command line arguments
const args = process.argv.slice(2);

// Handle help command
if (args.includes('--help') || args.includes('-h')) {
  console.log(`
Usage: node migrate.js [options]

Options:
  --help, -h    Show this help message
  --dry-run     Show what migrations would be applied without executing them

This script reads SQL files from the '${MIGRATIONS_DIR}' directory 
and logs them in alphabetical order (recommended chronological order).

Migration files should be named in chronological order, for example:
  001_create_users_table.sql
  002_add_email_column.sql
  003_create_posts_table.sql
`);
  process.exit(0);
}

// Run the migration logging
logMigrations();

