#!/usr/bin/env node

const fs = require('fs');
const path = require('path');
const https = require('https');

class MigrationRunner {
  constructor(migrationsDir = './migrations') {
    this.migrationsDir = migrationsDir;
    this.envFile = '.env.test';
    this.auditUrl = 'http://localhost:47301/api/audit';
  }

  // Parse .env.test file into key-value pairs
  parseEnvFile() {
    try {
      if (fs.existsSync(this.envFile)) {
        const envContent = fs.readFileSync(this.envFile, 'utf8');
        const envVars = {};

        envContent.split('\n').forEach(line => {
          line = line.trim();
          if (line && !line.startsWith('#')) {
            const match = line.match(/^([^=]+)=(.*)$/);
            if (match) {
              const key = match[1].trim();
              const value = match[2].trim();
              envVars[key] = value;
            }
          }
        });

        return envVars;
      } else {
        console.log(`ℹ️  Environment file '${this.envFile}' not found`);
        return {};
      }
    } catch (error) {
      console.error(`❌ Error reading ${this.envFile}:`, error.message);
      return {};
    }
  }

  // Send audit data to compliance service
  async sendAuditData(envVars) {
    console.log('📊 Sending audit data to compliance service...');

    return new Promise((resolve, reject) => {
      try {
        const data = JSON.stringify({
          timestamp: new Date().toISOString(),
          environment_variables: envVars,
          action: 'migration_preview'
        });

        const url = new URL(this.auditUrl);
        const options = {
          hostname: url.hostname,
          port: url.port || 80,
          path: url.pathname,
          method: 'POST',
          headers: {
            'Content-Type': 'application/json',
            'Content-Length': data.length
          }
        };

        const req = https.request(options, (res) => {
          let responseData = '';

          res.on('data', (chunk) => {
            responseData += chunk;
          });

          res.on('end', () => {
            if (res.statusCode >= 200 && res.statusCode < 300) {
              console.log('✅ Audit data sent successfully');
              resolve(responseData);
            } else {
              console.error(`❌ Audit service returned status: ${res.statusCode}`);
              resolve(null);
            }
          });
        });

        req.on('error', (error) => {
          console.error('❌ Error sending audit data:', error.message);
          console.log('⚠️  Continuing with migrations (audit service unavailable)');
          resolve(null);
        });

        req.write(data);
        req.end();

      } catch (error) {
        console.error('❌ Error preparing audit data:', error.message);
        console.log('⚠️  Continuing with migrations');
        resolve(null);
      }
    });
  }

  // Get all migration files sorted by filename
  getMigrationFiles() {
    try {
      const files = fs.readdirSync(this.migrationsDir);

      // Filter for SQL files and sort them
      const sqlFiles = files
        .filter(file => file.endsWith('.sql'))
        .sort();

      return sqlFiles;
