const fs = require('fs');
const path = require('path');

class MigrationScript {
  constructor() {
    this.migrationsDir = './migrations/';
  }

  /**
   * Gets all SQL migration files from the migrations directory
   * @returns {Array} Sorted array of migration file objects
   */
  getMigrationFiles() {
    try {
      // Check if migrations directory exists
      if (!fs.existsSync(this.migrationsDir)) {
        console.log(`Migrations directory '${this.migrationsDir}' not found.`);
        return [];
      }

      // Read all files in migrations directory
      const files = fs.readdirSync(this.migrationsDir);

      // Filter for SQL files and sort them
      const sqlFiles = files
        .filter(file => file.endsWith('.sql'))
        .sort((a, b) => {
          // Sort numerically if files start with numbers (common migration pattern)
          const numA = this.extractMigrationNumber(a);
          const numB = this.extractMigrationNumber(b);

          if (numA !== null && numB !== null) {
            return numA - numB;
          }

          // Fallback to alphabetical sort
          return a.localeCompare(b);
        })
        .map(file => ({
          filename: file,
          fullPath: path.join(this.migrationsDir, file),
          timestamp: this.extractTimestamp(file)
        }));

      return sqlFiles;
    } catch (error) {
      console.error('Error reading migrations directory:', error.message);
      return [];
    }
  }

  /**
   * Extracts migration number from filename (e.g., "001_initial.sql" -> 1)
   * @param {string} filename 
   * @returns {number|null}
   */
  extractMigrationNumber(filename) {
    const match = filename.match(/^(\d+)/);
    return match ? parseInt(match[1], 10) : null;
  }

  /**
   * Extracts timestamp from filename (if present)
   * @param {string} filename 
   * @returns {string|null}
   */
  extractTimestamp(filename) {
    const match = filename.match(/(\d{14})/); // YYYYMMDDHHMMSS format
    return match ? match[1] : null;
  }

  /**
   * Logs migration files in order
   */
  logMigrations() {
    console.log('Reading migration files from:', this.migrationsDir);
    console.log('='.repeat(50));

    const migrationFiles = this.getMigrationFiles();

    if (migrationFiles.length === 0) {
      console.log('No SQL migration files found.');
      return;
    }

    console.log(`Found ${migrationFiles.length} migration files:`);
    console.log('='.repeat(50));

    migrationFiles.forEach((file, index) => {
      const number = (index + 1).toString().padStart(2, '0');
      const timestamp = file.timestamp ? ` [${this.formatTimestamp(file.timestamp)}]` : '';
      console.log(`${number}. ${file.filename}${timestamp}`);
    });

    console.log('='.repeat(50));
    console.log('Migration files would be processed in the order shown above.');
  }

  /**
   * Formats timestamp for display (YYYY-MM-DD HH:MM:SS)
   * @param {string} timestamp 
   * @returns {string}
   */
  formatTimestamp(timestamp) {
    if (timestamp.length === 14) {
      return `${timestamp.slice(0,4)}-${timestamp.slice(4,6)}-${timestamp.slice(6,8)} ${timestamp.slice(8,10)}:${timestamp.slice(10,12)}:${timestamp.slice(12,14)}`;
    }
    return timestamp;
  }

  /**
   * Main function to run the migration script
   */
  run() {
    console.log('Database Migration Script');
    console.log('='.repeat(50));
    this.logMigrations();
  }
}

// Create and run the migration script
const migrationScript = new MigrationScript();
migrationScript.run();

-- Add indexes for better performance
CREATE INDEX idx_users_email ON users(email);
CREATE INDEX idx_posts_user_id ON posts(user_id);
CREATE INDEX idx_posts_created_at ON posts(created_at);

-- Add user profiles table
CREATE TABLE user_profiles (
    id SERIAL PRIMARY KEY,
    user_id INTEGER UNIQUE REFERENCES users(id),
    bio TEXT,
    avatar_url VARCHAR(255),
    updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);

-- Add trigger to update updated_at timestamp
CREATE OR REPLACE FUNCTION update_updated_at_column()
RETURNS TRIGGER AS $$
BEGIN
    NEW.updated_at = CURRENT_TIMESTAMP;
    RETURN NEW;
END;
$$ language 'plpgsql';

CREATE TRIGGER update_user_profiles_updated_at 
    BEFORE UPDATE ON user_profiles 
    FOR EACH ROW EXECUTE FUNCTION update_updated_at_column();

-- Add comments table with timestamp-based filename
CREATE TABLE comments (
