const { parseDatabaseUrl } = require('./migrate');

const testUrls = [
    'postgresql://user:password@localhost:5432/mydb',
    'mysql://root@localhost/mydb',
    'sqlite:/path/to/database.sqlite',
    'invalid-url',
    ''
];

console.log('Testing URL parsing:');
console.log('='.repeat(50));

testUrls.forEach((url, index) => {
    console.log(`\nTest ${index + 1}: ${url || '(empty)'}`);
    const parsed = parseDatabaseUrl(url);
    console.log('Parsed:', parsed);
});

const fs = require('fs');
const path = require('path');

class MigrationManager {
    constructor() {
        this.migrationsDir = path.join(__dirname, 'migrations');
    }

    // Get all migration files from the migrations directory
    getMigrationFiles() {
        try {
            // Check if migrations directory exists
            if (!fs.existsSync(this.migrationsDir)) {
                console.log('Migrations directory not found. Creating empty directory.');
                fs.mkdirSync(this.migrationsDir, { recursive: true });
                return [];
            }

            // Read all files in the migrations directory
            const files = fs.readdirSync(this.migrationsDir);

            // Filter for SQL files and sort them
            const sqlFiles = files
                .filter(file => file.endsWith('.sql'))
                .sort(); // Natural sort order (alphabetical/numerical)

            return sqlFiles;
        } catch (error) {
            console.error('Error reading migrations directory:', error.message);
            return [];
        }
    }

    // Log the migration files in order
    logMigrations() {
        console.log('\n=== Database Migration Script ===\n');
        console.log('Reading migration files from:', this.migrationsDir);

        const migrationFiles = this.getMigrationFiles();

        if (migrationFiles.length === 0) {
            console.log('\nNo migration files found in the migrations directory.');
            console.log('Add SQL files to the ./migrations/ folder with names like:');
            console.log('  001_initial_schema.sql');
            console.log('  002_add_users_table.sql');
            console.log('  003_add_indexes.sql');
            return;
        }

        console.log(`\nFound ${migrationFiles.length} migration file(s):\n`);

        // Log each migration file in order
        migrationFiles.forEach((file, index) => {
            console.log(`${index + 1}. ${file}`);

            // Optional: Read and log a preview of the SQL content
            try {
                const filePath = path.join(this.migrationsDir, file);
                const content = fs.readFileSync(filePath, 'utf8');
                const preview = content.split('\n')[0].substring(0, 100); // First line, max 100 chars
                if (preview.trim()) {
                    console.log(`   Preview: ${preview}${preview.length >= 100 ? '...' : ''}`);
                }
            } catch (error) {
                console.log(`   Could not read file: ${error.message}`);
            }

            console.log(''); // Empty line between migrations
        });

        console.log('\n=== Migration files would be applied in this order ===');
        console.log('To actually apply these migrations, you would:');
        console.log('1. Connect to your database');
        console.log('2. Execute each SQL file in order');
        console.log('3. Track which migrations have been applied');
    }

    // Main execution method
    run() {
        this.logMigrations();
    }
}

// Create and run the migration manager
const manager = new MigrationManager();
manager.run();

