const fs = require('fs');
const path = require('path');

// Directory containing migration files
const MIGRATIONS_DIR = './migrations';

function getMigrationFiles() {
  try {
    // Check if migrations directory exists
    if (!fs.existsSync(MIGRATIONS_DIR)) {
      console.log(`Migrations directory '${MIGRATIONS_DIR}' not found.`);
      return [];
    }

    // Read all files from the migrations directory
    const files = fs.readdirSync(MIGRATIONS_DIR);

    // Filter for SQL files and sort them in order
    const sqlFiles = files
      .filter(file => file.endsWith('.sql'))
      .sort((a, b) => {
        // Extract numbers from filenames for proper ordering
        const numA = extractNumber(a);
        const numB = extractNumber(b);
        return numA - numB;
      });

    return sqlFiles;
  } catch (error) {
    console.error('Error reading migrations directory:', error.message);
    return [];
  }
}

function extractNumber(filename) {
  // Extract numeric prefix from filename (e.g., 001_init.sql -> 1)
  const match = filename.match(/^(\d+)/);
  return match ? parseInt(match[1], 10) : 0;
}

function logMigrations() {
  console.log('=== Database Migration Script ===');
  console.log(`Reading migration files from: ${MIGRATIONS_DIR}\n`);

  const migrationFiles = getMigrationFiles();

  if (migrationFiles.length === 0) {
    console.log('No migration files found.');
    return;
  }

  console.log(`Found ${migrationFiles.length} migration file(s):\n`);

  // Log each migration file in order
  migrationFiles.forEach((file, index) => {
    console.log(`${index + 1}. ${file}`);
  });

  console.log('\n=== Migration order complete ===');
}

// Run the script
logMigrations();

