    const migrationsDir = path.join(__dirname, 'migrations');

    try {
        // Check if migrations directory exists
        if (!fs.existsSync(migrationsDir)) {
            console.log('No migrations directory found.');
            return [];
        }

        // Read all files in the migrations directory
        const files = fs.readdirSync(migrationsDir);

        // Filter for .sql files and sort them in alphabetical order
        const sqlFiles = files
            .filter(file => file.endsWith('.sql'))
            .sort();

        return sqlFiles;

    } catch (error) {
        console.error('Error reading migrations directory:', error.message);
        return [];
    }
}

// Main function
function main() {
    console.log('🚀 Starting migration audit process...\n');

    // Step 1: Read environment variables for audit
    const envVars = readEnvFile();

    // Step 2: Log audit information (mock)
    const auditData = logAuditInfo(envVars);

