            if (numA && numB) {
                return parseInt(numA[0]) - parseInt(numB[0]);
            }
            // If no numeric prefix, sort alphabetically
            return a.localeCompare(b);
        });

        return sqlFiles;
    } catch (error) {
        console.error('Error reading migrations directory:', error.message);
        return [];
