    // Check if .env.test file exists
    if (!fs.existsSync(envFilePath)) {
        console.log('Environment file not found:', envFilePath);
        return null;
    }

    try {
        // Read and parse the .env.test file
        const envContent = fs.readFileSync(envFilePath, 'utf8');
        const lines = envContent.split('\n');

        // Find DATABASE_URL line
        const dbUrlLine = lines.find(line => line.startsWith('DATABASE_URL='));

        if (!dbUrlLine) {
            console.log('DATABASE_URL not found in .env.test');
            return null;
        }

        // Extract the URL value (remove 'DATABASE_URL=' prefix)
        const databaseUrl = dbUrlLine.substring('DATABASE_URL='.length).trim();

        // Remove quotes if present
        const cleanUrl = databaseUrl.replace(/^['"]|['"]$/g, '');

        return cleanUrl;
    } catch (error) {
        console.error('Error reading .env.test file:', error.message);
        return null;
    }
}

// Function to validate and log database connection info
function logDatabaseConnection() {
    const databaseUrl = readDatabaseUrl();

    if (!databaseUrl) {
        console.log('\n⚠️  No database connection string found');
        console.log('Please create a .env.test file with DATABASE_URL=your_connection_string');
        return false;
    }

    try {
        // Parse database URL to extract components (for informational purposes)
        let dbType = 'unknown';
        let hostInfo = '';

        if (databaseUrl.startsWith('postgresql://') || databaseUrl.startsWith('postgres://')) {
            dbType = 'PostgreSQL';
            const match = databaseUrl.match(/\/\/([^@]+@)?([^\/]+)/);
            if (match && match[2]) {
                hostInfo = match[2];
            }
        } else if (databaseUrl.startsWith('mysql://')) {
            dbType = 'MySQL';
            const match = databaseUrl.match(/\/\/([^@]+@)?([^\/]+)/);
            if (match && match[2]) {
                hostInfo = match[2];
            }
