#!/usr/bin/env node

const fs = require('fs');
const path = require('path');

/**
 * Database migration script
 * 
 * Reads SQL files from ./migrations/ directory and logs each filename 
 * in the order they would be applied.
 */

class MigrationScript {
    constructor() {
        this.migrationsDir = path.join(__dirname, 'migrations');
    }

    /**
     * Get all migration files from the migrations directory
     * @returns {Array} Sorted array of migration file paths
     */
    getMigrationFiles() {
        try {
            // Check if migrations directory exists
            if (!fs.existsSync(this.migrationsDir)) {
                console.log(`Migrations directory '${this.migrationsDir}' does not exist. Creating it...`);
                fs.mkdirSync(this.migrationsDir, { recursive: true });
                return [];
            }

            // Read all files from migrations directory
            const files = fs.readdirSync(this.migrationsDir);

            // Filter for SQL files (files ending with .sql)
            const sqlFiles = files
                .filter(file => file.endsWith('.sql'))
                .map(file => path.join(this.migrationsDir, file));

            // Sort files by name (assuming they have timestamp prefixes)
            return sqlFiles.sort();

        } catch (error) {
            console.error('Error reading migrations directory:', error.message);
            return [];
        }
    }

    /**
     * Log migration files that would be applied
     */
    logMigrations() {
        console.log('📋 Database Migration Plan');
        console.log('='.repeat(50));

        const migrationFiles = this.getMigrationFiles();

        if (migrationFiles.length === 0) {
            console.log('No migration files found in ./migrations/ directory');
            console.log('Place your SQL migration files in the migrations folder with .sql extension');
            return;
        }

        console.log(`Found ${migrationFiles.length} migration file(s):\n`);

        migrationFiles.forEach((filePath, index) => {
            const fileName = path.basename(filePath);
            console.log(`${index + 1}. ${fileName}`);

            // Optional: Show a preview of the SQL content
            try {
                const content = fs.readFileSync(filePath, 'utf8');
                const preview = content.substring(0, 100).replace(/\n/g, ' ').trim();
                if (preview.length > 0) {
                    console.log(`   Preview: ${preview}${preview.length === 100 ? '...' : ''}`);
                }
            } catch (error) {
                console.log(`   Error reading file: ${error.message}`);
            }

            console.log('');
        });

        console.log('Migration files would be applied in the order shown above.');
    }

    /**
     * Run the migration script
     */
    run() {
        console.log('🚀 Starting migration inspection...\n');
        this.logMigrations();
    }
}

// Create and run the migration script
const migrationScript = new MigrationScript();
migrationScript.run();

-- Migration 001: Create users table
CREATE TABLE users (
    id SERIAL PRIMARY KEY,
    username VARCHAR(50) UNIQUE NOT NULL,
    email VARCHAR(100) UNIQUE NOT NULL,
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);

-- Create index on username for faster lookups
CREATE INDEX idx_users_username ON users(username);

-- Migration 003: Add comments table
CREATE TABLE comments (
    id SERIAL PRIMARY KEY,
    post_id INTEGER REFERENCES posts(id) ON DELETE CASCADE,
    user_id INTEGER REFERENCES users(id) ON DELETE CASCADE,
    comment TEXT NOT NULL,
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);

-- Create indexes for better performance
CREATE INDEX idx_comments_post_id ON comments(post_id);
CREATE INDEX idx_comments_user_id ON comments(user_id);

