#!/usr/bin/env node

const fs = require('fs');
const path = require('path');

// Default configuration
const DEFAULT_MIGRATIONS_DIR = './migrations';
const ENV_FILE = '.env.test';

// Show usage information
function showUsage() {
    console.log(`
Usage: node migrate_clean.js [migrations-dir] [env-file]

Arguments:
  migrations-dir  Directory containing SQL migration files (default: ${DEFAULT_MIGRATIONS_DIR})
  env-file        Environment file containing DATABASE_URL (default: ${ENV_FILE})

This script reads SQL migration files and logs their names in order.
It also reads DATABASE_URL from environment file for informational purposes.
`);
}

/**
 * Read all SQL files from the migrations directory
 * and sort them in alphabetical order (which should be timestamped)
 */
function getMigrationFiles(migrationsDir = DEFAULT_MIGRATIONS_DIR) {
    try {
        // Check if migrations directory exists
        if (!fs.existsSync(migrationsDir)) {
            console.log(`Migrations directory '${migrationsDir}' does not exist.`);
            return [];
        }

        // Read all files in the directory
        const files = fs.readdirSync(migrationsDir);

        // Filter for SQL files
        const sqlFiles = files.filter(file => 
            file.endsWith('.sql') && fs.statSync(path.join(migrationsDir, file)).isFile()
        );

        // Sort files alphabetically (which should maintain timestamp order)
        return sqlFiles.sort();

    } catch (error) {
        console.error('Error reading migrations directory:', error.message);
        return [];
    }
}

/**
 * Read DATABASE_URL from environment file for informational purposes
 */
function getDatabaseUrl(envFile = ENV_FILE) {
    try {
        if (!fs.existsSync(envFile)) {
            console.log(`Environment file '${envFile}' not found.`);
            return null;
        }

        const envContent = fs.readFileSync(envFile, 'utf8');
        const lines = envContent.split('\n');

        for (const line of lines) {
            // Skip comments and empty lines
            if (line.trim() === '' || line.trim().startsWith('#')) {
                continue;
            }

            const [key, value] = line.split('=').map(s => s.trim());
            if (key === 'DATABASE_URL' && value) {
                return value;
            }
        }

        console.log('DATABASE_URL not found in environment file.');
        return null;

    } catch (error) {
        console.error('Error reading environment file:', error.message);
        return null;
    }
}

/**
 * Simulate database connection (just log a message)
 */
function logConnection(databaseUrl) {
    if (databaseUrl) {
        // Mask password for security
        const maskedUrl = databaseUrl.replace(/:([^:@]+)@/, ':****@');
        console.log(`✅ Would connect to database: ${maskedUrl}`);
    } else {
        console.log('⚠️  No database connection configured');
    }
}

/**
 * Main function to process migrations
 */
function runMigrations(migrationsDir = DEFAULT_MIGRATIONS_DIR, envFile = ENV_FILE) {
    console.log(`Starting migration process for directory: ${migrationsDir}\n`);

    // Read and log database connection information
    const databaseUrl = getDatabaseUrl(envFile);
    logConnection(databaseUrl);
    console.log('');

    const migrationFiles = getMigrationFiles(migrationsDir);

    if (migrationFiles.length === 0) {
        console.log('No SQL migration files found.');
        return;
    }

    console.log(`Found ${migrationFiles.length} migration file(s):\n`);

    // Log each migration file that would be applied
    migrationFiles.forEach((file, index) => {
        console.log(`${index + 1}. ${file}`);
    });

    console.log(`\nMigration files listed in order. Total: ${migrationFiles.length} file(s)`);
    console.log('\nNote: This is a dry-run simulation. No actual database operations are performed.');
}

// Run the migration script
if (require.main === module) {
    // Check for help flag
    if (process.argv.includes('--help') || process.argv.includes('-h')) {
        showUsage();
        process.exit(0);
    }

    // Parse command line arguments
    const args = process.argv.slice(2);
    let migrationsDir = DEFAULT_MIGRATIONS_DIR;
    let envFile = ENV_FILE;

    // Simple argument parsing: first arg = migrations dir, second arg = env file
    if (args.length > 0) {
        migrationsDir = args[0];
    }
    if (args.length > 1) {
        envFile = args[1];
    }

    runMigrations(migrationsDir, envFile);
}

module.exports = {
    getMigrationFiles,
    getDatabaseUrl,
    runMigrations
};

